#!/usr/bin/env node
// Recorded model answers for the user's test PDF "BYU22S01 Statistics & Computation – Tutorial infographics" (7 sheets),
// written as the prompts in js/ai/prompts.js ask (explained steps, figure specs, code line by line, worked examples,
// dioramaPlan). tools/test-ingest.mjs serves them through a stubbed window.claude.sample, so the whole pipeline (chain →
// coverage → quality gate → repair → figures → dioramas) runs deterministically without a live model.
// Files: chain-01..07.json (good answers), chain-01-bad.json (pastes the page twice and cites the page crop three times),
// repair-01.json (the repair call's answer), gaps-03.json (the follow-up for the subsection chain-03 leaves out),
// figures-02.json (the figures call for the boxes chain-02 leaves bare), scene-*.json (authored dioramas).
// Run: node tools/fixtures/byu-stub/build.mjs   (writes next to this file)
import fs from 'fs'; import path from 'path'; import { fileURLToPath } from 'url';
const DIR = path.dirname(fileURLToPath(import.meta.url));
const out = (f, o) => { fs.writeFileSync(path.join(DIR, f), JSON.stringify(o, null, 1)); console.log('wrote', f); };
// the question thread: step k+1 answers what step k opens (the first answers the part's question)
function chain(meta, steps) { steps.forEach((s, i) => { s.id = 'S' + (i + 1); s.answers = i ? steps[i - 1].opens : meta.question; s.from = s.from || (i ? ['S' + i] : []); s.basis = s.basis || 'source-text'; s.demos = s.demos || []; s.figures = s.figures || []; }); return { ...meta, chain: steps, coverage: [] }; }
const flow = (caption, labels, dir = 'LR', edges) => ({ kind: 'flow', caption, dir, nodes: labels.map((l, i) => ({ id: 'n' + i, label: l })), ...(edges ? { edges } : {}) });
const contrast = (caption, wrong, right) => ({ kind: 'contrast', caption, wrong: { title: 'Mistaken', text: wrong }, right: { title: 'Instead', text: right } });
const trace = (caption, lines, output = [], animate = true) => ({ kind: 'codetrace', caption, lang: 'r', lines: lines.map(([code, note, state]) => ({ code, note, ...(state ? { state } : {}) })), output, animate });
const code = (lines, output, interpret) => ({ lang: 'r', lines: lines.map(([c, e]) => ({ code: c, explain: e })), output, interpret });

