    code: code([['seq(1, 10, 2)', 'by position: from = 1, to = 10, by = 2.'], ['seq(by = 2, to = 10, from = 1)', 'by name: the same three settings in another order.']], ['[1] 1 3 5 7 9', '[1] 1 3 5 7 9'], 'Same settings, same sequence: names make a call readable and order-proof.'),
