    check: { q: 'After read.csv(), str(dat) shows TotalSleep as chr. What will mean(dat$TotalSleep) do?', a: 'Warn and return NA: the column is text and must be converted (or the file cleaned) first.', figure: flow('Check the type before you compute.', ['read.csv()', 'str(dat): chr', 'convert', 'mean()'], 'LR') },
