    check: { q: 'Why does se() drop NAs before length(x)?', a: 'Otherwise length() would count the 4 missing values too (n = 62 instead of 58) and sd() would return NA.', figure: { kind: 'bars', caption: 'Counting with and without the NAs.', categories: ['length with NAs', 'length without'], series: [{ name: 'n', values: [62, 58] }] } },
    bodies: ['se', 'x', 'sd()', 'sqrt()'], demos: [{ type: 'scene', title: 'The function machine', purpose: 'How does a function turn an input into an output, step by step?', technique: 'card', request: 'A function machine on a workbench: a hopper labelled x receives a row of value-tokens (some marked NA), a sieve removes the NA tokens, a counter shows n, a dial computes sd ÷ √n and a tray outputs the SE token. Lessons: feed the sleep data; watch NAs drop; see n = 58; read 0.605.' }],
