c01.dioramaPlan = [{ subsection: '1.0', count: 0, why: 'static anatomy: the flow figure shows it' }, ...['1.1', '1.2', '1.3', '1.4', '1.5', '1.6'].map(s => ({ subsection: s, count: 0, why: 'a rule about syntax; figures suffice' })), { subsection: 'p1-7', count: 1, why: 'input → processing → output is a process: a function machine' }];
out('chain-01.json', c01);

// the bad answer the quality gate must catch: page 1 pasted twice (S1 and S2), the page crop cited three times
const PAGE1 = 'Anatomy of an R function Any word followed by brackets is a function. Learn its parts once. INPUT 3.3 8.3 12.5 16.5 NA dat$TotalSleep : hours of sleep for 62 mammals. 4 are NA (missing). mean() x = the data na.rm = TRUE / FALSE OUTPUT with na.rm = TRUE [1] 10.53276 left at the default [1] NA 2 Function name the verb: what to do 3 Arguments : the inputs. They live inside the brackets, separated by commas. avg <- mean ( dat$TotalSleep, na.rm = TRUE ) 1 Store the output avg <- saves it as an object. Read <- as “gets”. 4 Matched by position the first input fills the first argument, x (the data) 5 Named: name = value overrides the default, which is na.rm = FALSE';
const bad = JSON.parse(JSON.stringify(c01));
bad.chain[0] = { ...bad.chain[0], statement: PAGE1, explain: [], code: null, figures: ['fig-p1-1'], intuitionFigure: undefined };
bad.chain[1] = { ...bad.chain[1], statement: PAGE1, explain: [], code: null, examples: [], figures: ['fig-p1-1'] };
bad.chain[4] = { ...bad.chain[4], figures: ['fig-p1-1'] };
out('chain-01-bad.json', bad);
out('repair-01.json', { steps: [c01.chain[0], c01.chain[1]].map(s => ({ ...s, demos: undefined })) });

// ============================================================ 02 · The function checklist
const grp = (section, title, statement, para, lines, opens, extra = {}) => ({ section, kind: 'remark', title, ref: `Group ${section.split('.')[1]}, p. 2`, pages: [2], statement, explain: [{ text: para }], code: code(lines, [], extra.interpret || 'Each line is a typical use; the comment says what comes back.'), opens, ...extra });
const c02 = chain({ title: '02 · The function checklist', summary: 'The 58 functions of the course, grouped in the order an analysis uses them, with what each does and one typical call.', question: 'Which R functions does a whole analysis need, and in what order are they used?' }, [
  { section: '2.0', kind: 'remark', title: 'How to use the checklist', ref: 'p. 2', pages: [2], statement: 'The sheet lists 58 functions in nine groups that follow an analysis from setting up to programming; tick what you can use without looking it up and circle what to practise.',
    explain: [{ text: 'Tags say where each function appears in the course: CP computational practice, P practical, L lecture, and a star for a bonus function not yet in the course files. The groups run in the order of real work: set up, import, inspect, build and pick, summarise, plot, probability, test and model, program.', figure: flow('The nine groups, in the order of an analysis.', ['1 set up', '2 import', '3 inspect', '4 build & pick', '5 summarise', '6 plot', '7 probability', '8 test & model', '9 program'], 'LR') }],
    terms: [{ term: 'CP / P / L / ★', meaning: 'computational practice / practical / lecture / bonus, where the function is taught' }],
    intuition: 'The checklist is the route of an analysis, from opening the folder to writing your own tools.', intuitionFigure: flow('A route, not a dictionary.', ['folder', 'data', 'look', 'answer'], 'LR'),
    misconception: 'Learning functions alphabetically is efficient. Learning them by purpose shows when to use each.', misconceptionFigure: contrast('Group by purpose.', 'A–Z list of functions.', 'Functions grouped by the step of the analysis they serve.'),
    check: { q: 'Into which group does str() go, and why there?', a: 'Inspect (group 3): you look at the types of the columns before testing anything.', figure: flow('Inspect before you test.', ['import', 'str()', 'test'], 'LR') }, opens: 'What do you set up once per project before any analysis?' },
  grp('2.1', 'Set up once per project', 'getwd() shows the folder R is in, setwd() changes it, install.packages() downloads a package once, library() loads it in every session.', 'A package is downloaded to your computer only once with install.packages(), but it must be loaded with library() in every new R session before its functions exist. The working directory decides where read.csv() looks for files, so check it with getwd() first.', [['getwd()', 'which folder R is in'], ['setwd("~/stats")', 'make ~/stats the working folder'], ['install.packages("viridisLite")', 'download a package, once only'], ['library(viridisLite)', 'load it, in every session']], 'How do you bring a data file into R?',
    { terms: [{ term: 'package', meaning: 'a bundle of extra functions; installed once, loaded each session' }, { term: 'working directory', meaning: 'the folder R reads files from and saves files to' }], intuition: 'Installing buys the book; library() takes it off the shelf each day.', intuitionFigure: flow('Install once, load each session.', ['install.packages()', 'on disk', 'library() each session', 'functions ready'], 'LR'), misconception: 'install.packages() is needed every session. Only library() is.', misconceptionFigure: contrast('Once versus every session.', 'install.packages() every time I open R.', 'install once; library() every session.'), check: { q: 'R says "could not find function viridis". What two causes are likely?', a: 'The package is not installed, or it is installed but not loaded with library().', figure: flow('Two checks.', ['installed?', 'loaded with library()?'], 'TB') } }),
  grp('2.2', 'Import', 'read.csv() reads a comma-separated file into a data frame.', 'read.csv("mammal_sleep_flying.csv") looks for the file in the working directory and returns a data frame: one row per mammal, one column per variable. Store it with dat <- so that later functions can use it.', [['dat <- read.csv("mammal_sleep_flying.csv")', 'read the file into a data frame called dat']], 'What should you look at before you test anything?',
    { terms: [{ term: 'data frame', meaning: 'a table: rows are cases, columns are variables' }, { term: '.csv', meaning: 'comma-separated values: a plain-text table' }], intuition: 'read.csv() pours the spreadsheet into R as a table.', misconception: 'read.csv() opens the file wherever it is. It only looks in the working directory unless you give a path.', misconceptionFigure: contrast('Where R looks.', 'R finds the file anywhere.', 'R looks in getwd() unless you give the full path.'), check: { q: 'What does dat <- read.csv("sleep.csv") do if sleep.csv is in another folder?', a: 'It fails with "cannot open file … No such file or directory".', figure: flow('Fix the path.', ['getwd()', 'setwd() or full path', 'read.csv()'], 'LR') } }),
  grp('2.3', 'Inspect: always look before you test', 'View(), head(), str(), summary(), dim(), class(), table() and levels() show the data before any test.', 'head(dat) prints the first 6 rows; str(dat) shows every column with its type; summary(dat) gives quick statistics per column, including the number of NAs; dim(dat) gives rows × columns; class() says what type an object is; table() counts each category; levels() lists a factor\'s categories; View() opens a spreadsheet view.', [['str(dat)', 'types of each column'], ['summary(dat$TotalSleep)', 'min, quartiles, mean, max and the number of NAs'], ['dim(dat)', 'rows × columns, e.g. 62 rows'], ['table(dat$Danger)', 'how many mammals in each danger level']], 'How do you build vectors and pick parts of the data?',
    { terms: [{ term: 'factor', meaning: 'a categorical variable with a fixed set of levels' }], intuition: 'Look at the patient before you operate.', intuitionFigure: flow('Look first.', ['head()', 'str()', 'summary()', 'then test'], 'LR'), misconception: 'If R imported the file without an error, the columns are fine. A numeric column can arrive as text; str() reveals it.', misconceptionFigure: contrast('No error ≠ right types.', 'Imported without error → ready.', 'str() first: a number column may be chr.'), check: { q: 'Which function tells you how many NAs TotalSleep has?', a: 'summary(dat$TotalSleep) (it reports NA\'s: 4); or sum(is.na(dat$TotalSleep)).', figure: { kind: 'bars', caption: 'Values present and missing in TotalSleep.', categories: ['present', 'NA'], series: [{ name: 'mammals', values: [58, 4] }] } } }),
  grp('2.4', 'Build & pick', 'c(), seq() and rep() build vectors; dat[row, col] and dat$col pick parts; length(), as.factor(), as.numeric(), is.na() and which.max() describe and convert them.', 'c(12, 15, 9) combines values into a vector. dat[2, 3] picks row 2, column 3; dat$TotalSleep picks a column by name. length() counts values; as.factor() treats numbers as categories (danger 1–5); as.numeric() converts text to numbers; is.na() marks missing values; which.max() gives the position of the largest value.', [['x <- c(12, 15, 9)', 'a vector of three numbers'], ['dat[2, ]', 'all columns of row 2'], ['dat$Danger <- as.factor(dat$Danger)', 'danger levels as categories'], ['which.max(dat$TotalSleep)', 'the row of the longest sleeper']], 'Which numbers summarise a column?',
    { terms: [{ term: 'vector', meaning: 'an ordered set of values of one type' }, { term: 'dat[row, col]', meaning: 'pick by position; leave a side empty for all rows or all columns' }], intuition: 'Rows are animals, columns are measurements: [row, col] is a grid reference.', intuitionFigure: { kind: 'table', caption: 'dat[2, 3]: row 2, column 3.', columns: ['', 'col 1', 'col 2', 'col 3'], rows: [['row 1', '·', '·', '·'], ['row 2', '·', '·', 'here'], ['row 3', '·', '·', '·']], highlight: [[1, 3]] }, misconception: 'dat[3] is row 3. For a data frame dat[3] is column 3; use dat[3, ] for the row.', misconceptionFigure: contrast('Row or column?', 'dat[3] = third row.', 'dat[3] = third column; dat[3, ] = third row.'), check: { q: 'How do you get the TotalSleep of row 10?', a: 'dat$TotalSleep[10], or dat[10, "TotalSleep"].' } }),
  grp('2.5', 'Summarise', 'mean(), median(), sd(), min(), max(), sum(), IQR(), log() and log10() summarise a column.', 'mean() and median() give the centre (watch the NAs: na.rm = TRUE); sd() and IQR() give the spread, IQR being the range of the middle 50%; min() and max() the extremes; sum() adds up, and on a logical vector it counts the TRUEs; log() and log10() tame skewed data such as body mass.', [['median(dat$TotalSleep, na.rm = TRUE)', 'the middle value'], ['IQR(dat$TotalSleep, na.rm = TRUE)', 'spread of the middle 50%'], ['sum(dat$TotalSleep > 12, na.rm = TRUE)', 'counts mammals sleeping more than 12 h (TRUE counts as 1)'], ['log10(dat$BodyWt)', 'body mass on a log scale']], 'How do you see the data as a picture?',
    { terms: [{ term: 'IQR', meaning: 'interquartile range: third quartile minus first quartile' }, { term: 'log10', meaning: 'logarithm base 10: 0.01 → −2, 1000 → 3' }], intuition: 'Centre, spread and extremes are the three questions every summary answers.', intuitionFigure: { kind: 'numberline', caption: 'Centre, spread and extremes on one axis (sleep, hours).', min: 0, max: 20, step: 5, points: [{ x: 10.5, label: 'mean ≈ 10.5' }], intervals: [{ from: 2, to: 20, label: 'min … max' }] }, misconception: 'sum() only adds numbers. On TRUE/FALSE values it counts the TRUEs, which makes it a counter.', misconceptionFigure: contrast('sum() counts TRUEs.', 'sum(x > 12) adds the values above 12.', 'sum(x > 12) counts how many are above 12.'), check: { q: 'Why might the median be better than the mean for body mass?', a: 'Body mass is very skewed (0.005 to 6,654 kg): a few giants drag the mean up; the median is not moved by them.', figure: contrast('Skew drags the mean.', 'mean = a typical mammal.', 'median = the typical mammal; the mean follows the elephants.') } }),
  grp('2.6', 'Plot (see sheet 04)', 'plot(), hist(), boxplot(), barplot(), points(), lines(), abline(), legend() and par() draw and annotate graphs.', 'plot(x, y) draws a scatterplot of y against x; hist() a histogram; boxplot(y ~ group) one box per group; barplot() bars. points(), lines() and abline() add dots, lines and a straight line to an existing plot; legend() adds the key of colours and symbols; par(mfrow = c(1, 2)) puts several plots side by side.', [['hist(dat$TotalSleep)', 'histogram of sleep'], ['boxplot(TotalSleep ~ Danger, data = dat)', 'one box per danger level'], ['abline(h = 10.5, lty = 2)', 'add a dashed horizontal line at 10.5 h']], 'Which functions answer probability questions?',
    { terms: [{ term: 'y ~ x', meaning: 'formula: y as a function of x (response ~ explanatory)' }], intuition: 'plot() builds the canvas; points(), lines() and abline() draw on it.', intuitionFigure: flow('Canvas, then layers.', ['plot()', 'points()', 'abline()', 'legend()'], 'LR'), misconception: 'abline() makes a new plot. It adds to the current one.', misconceptionFigure: contrast('Add, do not replace.', 'abline() draws a new graph.', 'abline() adds a line to the open graph.'), check: { q: 'Which call draws one box per group?', a: 'boxplot(y ~ group, data = dat).', figure: flow('Formula to boxes.', ['y ~ group', 'boxplot()', 'one box per group'], 'LR') } }),
  grp('2.7', 'Probability (see sheet 05)', 'dbinom(), pbinom(), rbinom(), dpois(), dnorm(), pnorm(), qnorm() and rnorm() compute probabilities, quantiles and random values.', 'The first letter says the question: d = density or P(exactly x), p = probability of x or less, q = the value that cuts off a probability, r = random values. The rest of the name is the distribution: binom, pois, norm. Sheet 05 works through each with the natural-killer-cell example.', [['dbinom(2, size = 10, prob = 0.07)', 'P(exactly 2 of 10)'], ['pnorm(1.96)', 'area left of 1.96, about 0.975'], ['rnorm(5, mean = 165.1, sd = 7.07)', 'five random heights']], 'Which functions test hypotheses and fit models?',
    { terms: [{ term: 'd p q r', meaning: 'density, probability (cumulative), quantile, random' }], intuition: 'Four questions, one family of functions per distribution.', intuitionFigure: { kind: 'table', caption: 'Prefix + distribution = function.', columns: ['', 'binom', 'norm'], rows: [['d', 'dbinom', 'dnorm'], ['p', 'pbinom', 'pnorm'], ['q', 'qbinom', 'qnorm'], ['r', 'rbinom', 'rnorm']] }, misconception: 'dnorm() gives a probability. For a continuous variable it gives the height of the curve; probabilities are areas (pnorm).', misconceptionFigure: contrast('Height versus area.', 'dnorm(0) = P(X = 0).', 'dnorm(0) = 0.399 is a height; P(X = 0) = 0.'), check: { q: 'Which function gives P(X ≤ 3) for a binomial?', a: 'pbinom(3, size, prob).', figure: { kind: 'distribution', dist: 'binomial', params: { size: 10, prob: 0.07 }, caption: 'pbinom(3, 10, 0.07): the bars up to 3.', shade: { to: 3, label: 'P(X ≤ 3)' } } } }),
  grp('2.8', 'Test & model (see sheet 06)', 'shapiro.test(), t.test(), wilcox.test(), chisq.test(), lm(), summary(fit) and cor() test hypotheses and fit models.', 'shapiro.test() asks whether data are close to normal; t.test() compares means; wilcox.test() is its rank-based version for weak or non-normal data; chisq.test() compares counts with expected counts; lm() fits a straight line y = mx + c and summary(fit) reports the slope, intercept and p-values; cor() gives the correlation r.', [['shapiro.test(dat$TotalSleep)', 'is sleep close to normal?'], ['fit <- lm(TotalSleep ~ log10(BodyWt), data = dat)', 'fit a line'], ['summary(fit)', 'slope, intercept, p']], 'How do you write your own repeated steps?',
    { terms: [{ term: 'lm()', meaning: 'linear model: fits y = intercept + slope × x by least squares' }], intuition: 'Sheet 06 is the map from your data to the right one of these.', intuitionFigure: flow('Which family?', ['measured → t.test', 'ranks → wilcox.test', 'counts → chisq.test', 'two variables → lm / cor'], 'TB'), misconception: 'A significant shapiro.test() is good news. A small p means the data are NOT normal.', misconceptionFigure: contrast('Read Shapiro the right way.', 'p < 0.05 → normal.', 'p > 0.05 → normal enough; p < 0.05 → not normal.'), check: { q: 'Which function compares counts with an expected 3:1 ratio?', a: 'chisq.test(obs, p = c(0.75, 0.25)).', figure: flow('Counts against a ratio.', ['observed counts', 'expected 3:1', 'chisq.test()'], 'LR') } }),
  grp('2.9', 'Program', 'function(x) { } writes your own function, for (i in 1:n) repeats a step, if () { } else chooses a branch, sapply() applies a function to each element, ?name opens help.', 'A for loop runs its body once for each value of i; if () { } else { } runs one of two branches depending on a TRUE/FALSE condition; sapply(x, f) applies f to every element of x and collects the results, often replacing a loop.', [['for (i in 1:3) print(i^2)', 'prints 1, 4, 9'], ['if (mean(x) > 12) "high" else "low"', 'choose a branch'], ['sapply(1:3, function(i) i^2)', 'the same squares as a vector: 1 4 9']], 'How many of the 58 can you use without looking them up?',
    { terms: [{ term: 'loop', meaning: 'repeat a step for each value' }, { term: 'sapply()', meaning: 'apply a function to each element and simplify the result to a vector' }], intuition: 'A loop is a conveyor: the same machine handles each item in turn.', intuitionFigure: trace('for (i in 1:3) print(i^2)', [['i = 1', 'print 1'], ['i = 2', 'print 4'], ['i = 3', 'print 9']], ['[1] 1', '[1] 4', '[1] 9']), misconception: 'Loops are always needed to repeat work in R.', check: { q: 'What does sapply(c(4, 9, 16), sqrt) return?', a: '2 3 4.', figure: trace('sqrt applied to each element.', [['4', '→ 2'], ['9', '→ 3'], ['16', '→ 4']], ['[1] 2 3 4'], false) } }),
  { section: 'p2-10', kind: 'remark', title: 'Your score out of 58', ref: 'p. 2', pages: [2], statement: 'Counting the ticks gives a score out of 58; the circled functions are your practice list for the next session.',
    explain: [{ text: 'The score is a self-test, not a grade: retrieval practice (trying to recall before looking) is one of the most effective ways to learn. Re-take the checklist after each practical and watch the circled set shrink.' }],
    terms: [{ term: 'retrieval practice', meaning: 'learning by recalling from memory rather than re-reading' }],
    intuition: 'The score is a map of what to practise next.', intuitionFigure: { kind: 'bars', caption: 'Ticks and circles across the nine groups (your own counts go here).', categories: ['ticked', 'circled'], series: [{ name: 'functions', values: [0, 58] }] },
    misconception: 'A low score means you are behind. It means you have a precise practice list.', misconceptionFigure: contrast('A score is a plan.', 'Low score = failure.', 'Low score = a short, precise list to practise.'),
    check: { q: 'Why tick before looking things up?', a: 'Recalling first is the practice; looking up first only tests recognition.', figure: flow('Recall, then check.', ['try to recall', 'check', 'circle the misses'], 'LR') }, opens: 'What goes wrong when you use these functions, and how do you read R\'s messages?' }]);
