// ============================================================ 06 · Which test?
const c06 = chain({ title: '06 · Which test?', summary: 'Bradley\'s tests-of-inference tree: start with the kind of data, then what you compare; read p, and know the two ways to be wrong.', question: 'Which statistical test fits your data and your question, and how do you read its result?' }, [
  { section: '6.0', kind: 'definition', title: 'The decision tree', ref: 'p. 6', pages: [6], statement: 'Choose a test in two moves: first the kind of data (measured, weakly measured, categorical counts, two variables), then what you compare.',
    explain: [{ text: 'Measured data are continuous and roughly normal; weakly measured data are ranks, scores or non-normal; categorical counts say how many land in each group; two variables ask whether y is related to x. Each branch then splits by the comparison (one sample, two independent, paired, three or more), and every leaf names an R function.', figure: { kind: 'tree', caption: 'Start with your data, then what you compare.', root: { label: 'your data', children: [{ label: 'measured', edge: 'normal', children: [{ label: 't.test / aov' }] }, { label: 'weakly measured', edge: 'ranks', children: [{ label: 'wilcox.test' }] }, { label: 'categorical counts', edge: 'counts', children: [{ label: 'chisq.test' }] }, { label: 'two variables', edge: 'related?', children: [{ label: 'lm / cor.test' }] }] } } }],
    terms: [{ term: 'test of inference', meaning: 'a procedure that judges whether a pattern in a sample is likely to hold in the population' }],
    intuition: 'The tree is a key, like the keys used to identify plants.', intuitionFigure: flow('Two questions, then the test.', ['what data?', 'what comparison?', 'R function'], 'LR'),
    misconception: 'Pick the test that gives a significant p. The data and the question choose the test before you see the result.', misconceptionFigure: contrast('Choose first.', 'Try tests until p < 0.05.', 'Choose by data and question, then run once.'),
    check: { q: 'Counts of flying and non-flying mammals in five danger levels: which branch?', a: 'Categorical counts: a contingency table, χ² test of association.', figure: flow('Counts in a table.', ['categorical counts', 'two ways of grouping', 'chisq.test(table(a, b))'], 'LR') }, opens: 'Which tests fit measured, roughly normal data?' },
  { section: 'p6-1', kind: 'result', title: 'Measured data: Z, t and ANOVA', ref: 'Measured data branch, p. 6', pages: [6], figures: ['fig-p6-1'], statement: 'For continuous, roughly normal data (check with hist() and shapiro.test(): p > 0.05 is normal enough): one sample with σ known → Z test; σ unknown → t.test(x, mu = 1.9); paired → t.test(a, b, paired = TRUE); two independent → t.test(y ~ group, data = dat); three or more → summary(aov(y ~ group)).',
    explain: [{ text: 'All these tests compare means against the variation within the data. A Z test uses a known population σ: compute z, then the two-sided p is 2 * pnorm(-abs(z)). Usually σ is unknown and estimated from the sample, which widens the reference curve: that is the t distribution. Paired samples (the same subjects before and after) are tested on their differences; independent groups compare two means; with three or more groups ANOVA asks whether any mean differs.', figure: { kind: 'tree', caption: 'The measured-data branch of the tree.', root: { label: 'measured, normal', children: [{ label: '1 sample, σ known: Z' }, { label: '1 sample, σ unknown: t.test(x, mu)' }, { label: '2 paired: t.test(paired = TRUE)' }, { label: '2 independent: t.test(y ~ group)' }, { label: '3+: aov' }] } } }],
    code: code([['shapiro.test(x)', 'are the data close to normal? p > 0.05: normal enough'], ['z <- 2.1; 2 * pnorm(-abs(z))', 'two-sided p for a Z test with z = 2.1'], ['t.test(x, mu = 1.9)', 'one-sample t test against the known mean 1.9'], ['t.test(y ~ group, data = dat)', 'two independent samples'], ['summary(aov(y ~ group))', 'three or more groups']], ['[1] 0.03572884'], 'z = 2.1 is significant at the 5% level (p = 0.036).'),
    examples: [{ title: 'A paired t test on the classic sleep data (added)', origin: 'added', problem: 'Ten patients took two sleep drugs; extra hours of sleep were recorded for each drug (R\'s built-in data sleep). Does the second drug give more sleep?', solution: [{ text: 'Each patient took both drugs, so the samples are paired: test the ten differences.' }, { text: 'with(sleep, t.test(extra[group == 1], extra[group == 2], paired = TRUE)) gives a mean difference of −1.58 h, t = −4.06, df = 9.' }], answer: 'p = 0.0028: the second drug gives about 1.6 h more sleep; very unlikely by chance.', source: { title: 'The probable error of a mean', authors: 'Student', year: 1908, doi: '10.1093/biomet/6.1.1' } }],
    terms: [{ term: 'paired samples', meaning: 'two measurements on the same subjects; test the differences' }, { term: 'ANOVA', meaning: 'analysis of variance: compares three or more group means at once' }, { term: 't distribution', meaning: 'like the normal but with heavier tails, used when σ is estimated' }],
    intuition: 'A t test asks whether the gap between means is large compared with the noise.', intuitionFigure: { kind: 'distribution', dist: 't', params: { df: 9 }, caption: 't with 9 df; the sleep data\'s t = −4.06 lies far out in the tail.', marks: [{ x: -4.06, label: 't = −4.06' }], xlabel: 't' },
    misconception: 'Paired data can be tested as two independent samples. That ignores that each subject is its own control and wastes power.', misconceptionFigure: contrast('Pairing matters.', 'Before and after = two groups.', 'Before and after = one set of differences.'),
    check: { q: 'Weights of 12 rats before and after a diet: which call?', a: 't.test(before, after, paired = TRUE) (if the differences are roughly normal).', figure: flow('Same rats twice.', ['paired', 't.test(a, b, paired = TRUE)'], 'LR') }, opens: 'What if the data are ranks or not normal?' },
  { section: 'p6-2', kind: 'result', title: 'Weakly measured data: rank tests', ref: 'Weakly measured branch, p. 6', pages: [6], statement: 'For ranks, scores or non-normal data: two independent samples → Mann–Whitney U, wilcox.test(y ~ group); two paired samples → Wilcoxon signed-rank, wilcox.test(a, b, paired = TRUE).',
    explain: [{ text: 'Rank tests replace the values by their ranks (1st, 2nd, 3rd …) and compare the ranks, so a few extreme values or a skewed shape cannot dominate. They ask whether one group tends to have larger values than the other, rather than comparing means.', figure: flow('From values to ranks.', ['values: 2.1, 9.8, 3.4', 'ranks: 1, 3, 2', 'compare rank sums'], 'LR') }],
    code: code([['wilcox.test(y ~ group, data = dat)', 'Mann–Whitney U: do two independent groups differ in their ranks?'], ['wilcox.test(a, b, paired = TRUE)', 'Wilcoxon signed-rank: ranks of the paired differences']], [], 'Use these when the histogram is skewed or the scale is only ordinal.'),
    terms: [{ term: 'rank', meaning: 'the position of a value when all values are sorted' }, { term: 'non-parametric', meaning: 'does not assume a specific distribution such as the normal' }],
    intuition: 'A race result keeps the order and forgets the times.', intuitionFigure: contrast('Values versus ranks.', 'One extreme value drags the mean.', 'Ranks: the extreme value is just "1st".'),
    misconception: 'Rank tests are always weaker, so avoid them. On skewed data they can be more powerful than a t test.', misconceptionFigure: contrast('Fit the test to the data.', 'Rank tests waste information.', 'On skewed data they are often the better tool.'),
    check: { q: 'Pain scores 0–10 in two independent groups: which test?', a: 'Mann–Whitney U, wilcox.test(score ~ group): scores are ordinal.', figure: flow('Ordinal scores.', ['weakly measured', '2 independent', 'wilcox.test'], 'LR') }, opens: 'Which tests fit counts in categories?' },
  { section: 'p6-3', kind: 'result', title: 'Categorical counts: χ² and Fisher', ref: 'Categorical counts branch, p. 6', pages: [6], statement: 'Counts against an expected ratio → χ² goodness of fit, chisq.test(obs, p = props); two ways of grouping linked? → χ² test of association, chisq.test(table(a, b)); Fisher\'s exact test, fisher.test(table(a, b)), when an expected count is below 5. Use counts, never percentages.',
    explain: [{ text: 'χ² adds up (observed − expected)² / expected over all cells: big gaps between what you saw and what the hypothesis predicts make a big χ². Percentages hide the sample size, and the test needs it, so always give the counts. With small expected counts the χ² approximation fails and Fisher\'s exact test is used.', figure: { kind: 'bars', caption: 'Mendel\'s peas: observed counts against the 9:3:3:1 expectation (added example).', categories: ['round yellow', 'round green', 'wrinkled yellow', 'wrinkled green'], series: [{ name: 'observed', values: [315, 108, 101, 32] }, { name: 'expected', values: [312.75, 104.25, 104.25, 34.75] }], ylabel: 'seeds', extra: [{ what: 'Mendel\'s dihybrid counts', source: { title: 'Versuche über Pflanzen-Hybriden', authors: 'Mendel G', year: 1866 } }] } }],
    code: code([['obs <- c(315, 108, 101, 32)', 'Mendel\'s four seed classes'], ['chisq.test(obs, p = c(9, 3, 3, 1) / 16)', 'goodness of fit to the 9:3:3:1 ratio']], ['X-squared = 0.47002, df = 3, p-value = 0.9254'], 'The counts fit the 9:3:3:1 ratio very well: no evidence against it.'),
    examples: [{ title: 'Mendel\'s 9:3:3:1 (added)', origin: 'added', problem: '556 seeds: 315, 108, 101, 32. Do they fit 9:3:3:1?', solution: [{ text: 'Expected: 556 × 9/16 = 312.75; 104.25; 104.25; 34.75.' }, { text: 'χ² = 0.016 + 0.135 + 0.101 + 0.218 = 0.470 with 3 df.' }], answer: 'p = 0.925: the ratio fits.', source: { title: 'Versuche über Pflanzen-Hybriden', authors: 'Mendel G', year: 1866 } }],
    terms: [{ term: 'expected count', meaning: 'total × the proportion the hypothesis predicts' }, { term: 'contingency table', meaning: 'counts cross-classified by two groupings' }],
    intuition: 'χ² measures the distance between the counts you saw and the counts you expected.', intuitionFigure: flow('Observed versus expected.', ['observed', '− expected', 'squared ÷ expected', 'sum = χ²'], 'LR'),
    misconception: 'chisq.test() works on percentages. It needs counts; percentages lose n and give wrong p-values.', misconceptionFigure: contrast('Counts, never %.', 'chisq.test(c(57%, 19%, 18%, 6%))', 'chisq.test(c(315, 108, 101, 32))'),
    check: { q: 'A 2 × 2 table has a cell with expected count 3. Which test?', a: 'Fisher\'s exact test, fisher.test(table(a, b)).', figure: flow('Small counts.', ['expected < 5', 'fisher.test'], 'LR') }, opens: 'How do you test whether two variables are related?' },
  { section: 'p6-4', kind: 'result', title: 'Two variables: regression and correlation', ref: 'Two variables branch, p. 6', pages: [6], statement: 'Both well measured → regression lm(y ~ x) and correlation cor.test(x, y); ranks or weak measures → Spearman rank correlation, cor.test(x, y, method = "spearman").',
    explain: [{ text: 'Regression fits a line and asks whether its slope differs from zero; correlation measures how tightly the points follow a line. For sheet 04\'s body mass and sleep, r = −0.53: cor.test() tells whether such an r could arise by chance with this n. Spearman does the same on ranks, for monotonic but not straight relations or ordinal data.', figure: { kind: 'scatter', caption: 'A line through two measured variables (shape of sheet 04\'s trend).', points: [[-2, 18], [-1, 15], [0, 12], [1, 10], [2, 8], [3, 6], [3.8, 4]], fit: 'ols', xlabel: 'log10 body mass', ylabel: 'sleep (h)' } }],
    code: code([['fit <- lm(TotalSleep ~ log10(BodyWt), data = dat)', 'fit sleep as a straight-line function of log body mass'], ['summary(fit)', 'slope, intercept and the p-value of the slope'], ['cor.test(log10(dat$BodyWt), dat$TotalSleep)', 'is r = −0.53 different from 0?'], ['cor.test(x, y, method = "spearman")', 'rank correlation for ordinal or non-linear data']], [], 'The slope says how much sleep changes per tenfold increase in body mass.'),
    terms: [{ term: 'regression', meaning: 'fitting y = intercept + slope × x' }, { term: 'Spearman correlation', meaning: 'correlation of the ranks' }],
    intuition: 'Regression draws the line; correlation says how tight the cloud is around it.', intuitionFigure: contrast('Line versus tightness.', 'r is the slope.', 'Slope = steepness; r = tightness.'),
    misconception: 'A significant regression proves x causes y. In observational data it shows association only.', misconceptionFigure: contrast('Association, not cause.', 'Significant slope → x causes y.', 'Significant slope → x and y go together.'),
    check: { q: 'Ranks of 8 wines by two judges: which test?', a: 'Spearman: cor.test(judge1, judge2, method = "spearman").', figure: flow('Ranks.', ['two rankings', 'Spearman'], 'LR') }, opens: 'How do you read the p-value a test returns?' },
  { section: 'p6-5', kind: 'definition', title: 'Reading p', ref: 'Reading p, p. 6', pages: [6], statement: 'p is the chance of a result at least this extreme if H₀ were true; p ≤ 0.05 → reject H₀ (≤ 0.01 highly, ≤ 0.001 very highly significant); p > 0.05 is no evidence of a difference, not proof of none.',
    explain: [{ text: 'H₀, the null hypothesis, says there is no effect. A small p says the data would be surprising if H₀ were true. Testing many times inflates false alarms, so divide 0.05 by the number of tests (Bonferroni): with 5 tests, each must reach p ≤ 0.01.', figure: { kind: 'numberline', caption: 'The p scale of the sheet.', min: 0, max: 0.1, step: 0.01, points: [{ x: 0.001, label: '0.001' }, { x: 0.01, label: '0.01' }, { x: 0.05, label: '0.05' }], intervals: [{ from: 0, to: 0.05, label: 'reject H₀', closedR: true }, { from: 0.05, to: 0.1, label: 'no evidence', closedL: false }] } }],
    terms: [{ term: 'H₀', meaning: 'null hypothesis: no effect or no difference' }, { term: 'p-value', meaning: 'P(a result at least this extreme | H₀ true)' }, { term: 'Bonferroni', meaning: 'use 0.05 ÷ (number of tests) as the threshold' }],
    intuition: 'p asks: if nothing were going on, how often would I see something this striking?', intuitionFigure: { kind: 'distribution', dist: 'normal', params: { mean: 0, sd: 1 }, caption: 'Two-sided p for z = 2.1: both tails beyond ±2.1 (0.036).', shade: { from: 2.1, label: 'one tail' }, marks: [{ x: 2.1, label: '2.1' }, { x: -2.1, label: '−2.1' }] },
    misconception: 'p is the probability that H₀ is true. It is the probability of data this extreme if H₀ is true.', misconceptionFigure: contrast('Read p the right way round.', 'p = 0.03 → 3% chance H₀ is true.', 'p = 0.03 → such data in 3% of samples if H₀ were true.'),
    check: { q: 'Ten tests: what threshold does Bonferroni give?', a: '0.05 / 10 = 0.005.', figure: flow('Bonferroni.', ['0.05', '÷ 10 tests', '0.005 each'], 'LR') }, opens: 'In which two ways can a test be wrong?' },
  { section: 'p6-6', kind: 'definition', title: 'Two ways to be wrong', ref: 'p. 6', pages: [6], statement: 'Rejecting a true H₀ is a Type I error (a false positive, at rate α); not rejecting a false H₀ is a Type II error (a missed effect).',
    explain: [{ text: 'α is the threshold you chose (0.05): when H₀ is true, you will still reject it in 5% of studies. A Type II error happens when the effect is real but the sample is too small or noisy to show it. If you predicted a direction before seeing the data, use alternative = "greater" (or "less"); otherwise test two-sided.', figure: { kind: 'table', caption: 'The four outcomes of a test.', columns: ['', 'H₀ true', 'H₀ false'], rows: [['reject H₀', 'Type I: false positive (α)', 'correct'], ["don't reject", 'correct', 'Type II: missed effect']], highlight: [[0, 1], [1, 2]] } }],
    code: code([['t.test(x, mu = 1.9, alternative = "greater")', 'one-sided: only a mean above 1.9 counts as evidence']], [], 'Choose the direction before seeing the data.'),
    terms: [{ term: 'Type I error', meaning: 'false positive: rejecting a true H₀' }, { term: 'Type II error', meaning: 'false negative: missing a real effect' }, { term: 'α', meaning: 'the significance threshold, the Type I error rate' }],
    intuition: 'A smoke alarm can ring without fire (Type I) or stay silent during one (Type II).', intuitionFigure: contrast('Two alarms.', 'Ringing, no fire: Type I.', 'Fire, no ring: Type II.'),
    misconception: 'Not significant means no effect. It may be a Type II error: the study may simply be too small.', misconceptionFigure: contrast('Absence of evidence.', 'p > 0.05 → no effect.', 'p > 0.05 → no evidence; maybe too few data.'),
    check: { q: 'Lowering α from 0.05 to 0.01 makes which error rarer and which more likely?', a: 'Type I becomes rarer; Type II becomes more likely (real effects are harder to detect).', figure: contrast('A trade-off.', 'Smaller α helps everything.', 'Smaller α: fewer false alarms, more missed effects.') }, opens: 'How does a predator\'s eating rate depend on how much prey there is?' }]);
c06.dioramaPlan = c06.chain.map(s => ({ subsection: s.section, count: 0, why: 'a decision key: tree and table figures show it' }));
out('chain-06.json', c06);

// ============================================================ 07 · Functional responses
const holling = { kind: 'plot', caption: 'Holling\'s three curves; Type II drawn with the sheet\'s a, Th = 0.1, T = 1: it levels off at 1 ÷ 0.1 = 10 prey. (Type I and III: illustrative shapes.)', x: [0, 200], y: [0, 12], xlabel: 'prey density H', ylabel: 'prey eaten per predator Ha', curves: [{ expr: '0.06*x', label: 'Type I' }, { expr: 'a*x/(1+a*x*0.1)', label: 'Type II' }, { expr: '10*x^2/(x^2+3600)', label: 'Type III' }], hlines: [{ y: 10, label: 'plateau T ÷ Th = 10' }], animate: { param: 'a', from: 0.1, to: 1, period: 5 } };
const c07 = chain({ title: '07 · Functional responses', summary: 'How one predator\'s eating rate changes with prey density: Holling\'s Types I, II and III, the disc equation, and how to fit it with a straight line.', question: 'As prey become more common, how fast does one predator eat?' }, [
  { section: '7.0', kind: 'definition', title: 'Functional response', ref: 'p. 7', pages: [7], statement: 'A functional response is how each predator\'s eating rate changes with prey density; y is prey eaten per predator per unit time, Ha, and x is prey density, H. (Predator numbers rising instead is the numerical response.)',
    explain: [{ text: 'Holling (1959) found three shapes. Type I rises in a straight line. Type II rises and then levels off, because each catch costs handling time: with a = 0.5, Th = 0.1 and T = 1 the plateau is T ÷ Th = 10 prey, and the initial slope is a × T. Type III is S-shaped: slow at first, then steep, then level.', figure: holling }],
    terms: [{ term: 'Ha', meaning: 'prey eaten per predator per unit time' }, { term: 'H', meaning: 'prey density (prey per unit area)' }, { term: 'numerical response', meaning: 'the change in predator numbers with prey density' }],
    intuition: 'Imagine one fox in fields with more and more rabbits: at first more rabbits means more meals, but a fox can only eat so fast.', intuitionFigure: flow('More prey, but a ceiling.', ['more prey', 'more catches', 'handling fills the time', 'plateau'], 'LR'),
    misconception: 'Functional and numerical responses are the same thing. One is eating rate per predator, the other is how many predators there are.', misconceptionFigure: contrast('Per predator versus how many.', 'More prey → more predators = functional response.', 'Functional: each predator eats more; numerical: more predators.'),
    check: { q: 'On the sheet\'s Type II curve, what is the most a predator can eat in T = 1?', a: 'T ÷ Th = 1 ÷ 0.1 = 10 prey.', figure: { kind: 'plot', caption: 'The plateau of Type II.', x: [0, 200], y: [0, 12], curves: [{ expr: '0.5*x/(1+0.05*x)', label: 'Type II' }], hlines: [{ y: 10, label: '10' }] } }, opens: 'What does the straight-line Type I response mean for prey?' },
  { section: 'p7-1', kind: 'result', title: 'Type I: a straight line', ref: 'Type I card, p. 7', pages: [7], statement: 'In a Type I response the catch rises in step with prey density; nothing slows the predator down, as with a spider\'s web: more flies about, more caught.',
    explain: [{ text: 'Because catches are proportional to prey, each prey individual has the same chance of being eaten whatever the density: prey mortality is constant. The relation is linear, so it is fitted with simple regression, lm(Ha ~ H), whose slope is the attack rate times T.' }],
    code: code([['lm(Ha ~ H)', 'straight line through prey eaten against prey density: the slope is the capture rate per prey']], [], 'A constant slope means a constant share of prey eaten.'),
    terms: [{ term: 'prey mortality', meaning: 'the share of prey eaten per unit time' }],
    intuition: 'A web catches a fixed share of whatever flies past.', intuitionFigure: { kind: 'plot', caption: 'Type I: catches proportional to prey.', x: [0, 200], curves: [{ expr: '0.06*x', label: 'Type I' }] },
    misconception: 'More prey caught means a higher risk for each prey. In Type I the risk per prey stays the same.', misconceptionFigure: contrast('Total versus per prey.', 'More eaten → riskier for each.', 'Same share eaten: risk per prey constant.'),
    check: { q: 'If H doubles under Type I, what happens to Ha?', a: 'It doubles too: Ha is proportional to H.', figure: flow('Proportional.', ['H × 2', 'Ha × 2'], 'LR') }, opens: 'Why does the Type II curve level off?' },
  { section: 'p7-2', kind: 'result', title: 'Type II: handling time caps intake', ref: 'Type II card, p. 7', pages: [7], statement: 'In a Type II response every catch costs handling time (chase, kill, eat, digest), so intake levels off; e.g. small mammals eating gypsy-moth pupae.',
    explain: [{ text: 'At low density the predator spends almost all its time searching, so catches rise nearly in proportion to prey. As prey become common, more and more of the time goes into handling, which leaves less time to search, and the rate approaches a ceiling of T ÷ Th. Prey mortality is therefore highest when prey are scarce: at high density each prey has a smaller chance of being eaten.', figure: { kind: 'plot', caption: 'Type II: Ha = aHT / (1 + aHTh) with a = 0.5, Th = 0.1, T = 1 (the sheet\'s values).', x: [0, 200], y: [0, 12], curves: [{ expr: '0.5*x/(1+0.05*x)', label: 'Type II' }], hlines: [{ y: 10, label: 'T ÷ Th' }], points: [[100, 8.33, 'H = 100: 8.33']] } }],
    terms: [{ term: 'handling time Th', meaning: 'time spent on each prey caught (chase, kill, eat, digest)' }],
    intuition: 'A fast eater in a buffet is still limited by chewing.', intuitionFigure: { kind: 'bars', caption: 'Share of the time budget spent handling rises with prey density (Type II, a = 0.5, Th = 0.1).', categories: ['H = 10', 'H = 50', 'H = 200'], series: [{ name: 'handling share', values: [0.33, 0.71, 0.91] }] },
    misconception: 'With unlimited prey a predator eats without limit. Handling time caps it at T ÷ Th.', misconceptionFigure: contrast('A ceiling.', 'More prey → ever more eaten.', 'Ha → T ÷ Th = 10 at most.'),
    check: { q: 'At H = 100 (a = 0.5, Th = 0.1, T = 1), how many prey does one predator eat?', a: 'Ha = 0.5 × 100 / (1 + 0.5 × 100 × 0.1) = 50 / 6 = 8.33.', figure: { kind: 'plot', caption: 'Reading H = 100 off the curve.', x: [0, 200], y: [0, 12], curves: [{ expr: '0.5*x/(1+0.05*x)' }], vlines: [{ x: 100, label: 'H = 100' }], points: [[100, 8.33, '8.33']] } },
    demos: [{ type: 'scene', title: 'A predator\'s time budget', purpose: 'Why does handling time make the catch rate level off?', technique: 'topdown', request: 'Holling disc: a predator on a field of prey; it searches, catches, then handles each prey for Th seconds; prey density H and handling time Th are parameters; a readout shows catches per minute and the share of time spent handling; lessons: low density, high density, longer handling.' }],
    opens: 'What makes a response S-shaped?' },
  { section: 'p7-3', kind: 'result', title: 'Type III: S-shaped', ref: 'Type III card, p. 7', pages: [7], statement: 'In a Type III response predators get better as prey get common: they learn, or switch to the commonest prey; e.g. birds switching prey, hunters following scent.',
    explain: [{ text: 'At low density the predator rarely meets this prey and does not bother with it, so the curve starts flat. As the prey becomes common the predator learns or switches to it and the catch rate accelerates, until handling time caps it as in Type II. Prey mortality therefore rises, then falls: rare prey find a refuge in their rarity.', figure: { kind: 'plot', caption: 'Type III: slow start, steep middle, plateau (illustrative shape).', x: [0, 200], y: [0, 12], curves: [{ expr: '10*x^2/(x^2+3600)', label: 'Type III' }] } }],
    terms: [{ term: 'prey switching', meaning: 'a predator shifting its diet to whichever prey is commonest' }],
    intuition: 'You only start looking for mushrooms once you have spotted a few.', intuitionFigure: flow('Learning makes the S.', ['rare: ignored', 'common: learned', 'abundant: handling cap'], 'LR'),
    misconception: 'Type III is just a slower Type II. Its start is accelerating (S-shaped), which gives rare prey a refuge that Type II does not.', misconceptionFigure: contrast('The start differs.', 'Type III = flatter Type II.', 'Type III starts flat then accelerates: rare prey are spared.'),
    check: { q: 'Which type can stabilise a prey population at low density, and why?', a: 'Type III: the risk per prey falls as prey become rare, so a declining population is spared.', figure: flow('A refuge in rarity.', ['prey become rare', 'predators switch away', 'risk per prey falls'], 'LR') }, opens: 'Where does the Type II formula come from?' },
  { section: 'p7-4', kind: 'derivation', title: 'Holling\'s disc equation', ref: 'Where Type II comes from, p. 7', pages: [7], statement: 'Splitting one predator\'s time budget into searching and handling gives Ha = aHT / (1 + aHTh).',
    math: 'H_a=\\frac{aHT}{1+aHT_h}',
    derivation: [{ expr: 'T = T_{search} + T_{handling}', why: 'the total time is spent searching or handling' }, { expr: 'H_a = a\\,H\\,T_{search}', why: 'prey found while searching: area searched per unit time × density × search time' }, { expr: 'T_{handling} = H_a\\,T_h', why: 'each prey caught costs Th' }, { expr: 'H_a = aH(T - H_a T_h)', why: 'substitute T_search = T − T_handling' }, { expr: 'H_a(1 + aHT_h) = aHT', why: 'collect the Ha terms' }, { expr: 'H_a = \\frac{aHT}{1 + aHT_h}', why: 'divide' }],
    explain: [{ text: 'Every term has a meaning: a is the attack rate (area searched per unit time), Th the handling time per prey, T the total time and H the prey density. When H is small the denominator is close to 1 and Ha ≈ aHT, the straight start; when H is large, aHTh dominates and Ha → T ÷ Th, the plateau.', figure: flow('One time budget, two uses.', ['T total time', 'T search: finds a·H·T search prey', 'T handling = Ha · Th', 'Ha = aHT / (1 + aHTh)'], 'TB', [{ from: 'n0', to: 'n1' }, { from: 'n0', to: 'n2' }, { from: 'n1', to: 'n3' }, { from: 'n2', to: 'n3' }]) }],
    examples: [{ title: 'Ha at H = 100', origin: 'pdf', ref: 'values of p. 7', problem: 'a = 0.5, Th = 0.1, T = 1, H = 100.', solution: [{ text: 'Numerator aHT = 0.5 × 100 × 1 = 50.' }, { text: 'Denominator 1 + aHTh = 1 + 0.5 × 100 × 0.1 = 6.' }], answer: 'Ha = 50 / 6 = 8.33 prey.' }],
    terms: [{ term: 'a', meaning: 'attack rate: area searched per unit time' }, { term: 'T', meaning: 'total time available' }, { term: 'T_search, T_handling', meaning: 'time spent searching / handling' }],
    intuition: 'The predator\'s day is a pie of searching and handling; more prey makes the handling slice grow.', intuitionFigure: { kind: 'bars', caption: 'Searching and handling time out of T = 1 at three densities (a = 0.5, Th = 0.1).', categories: ['H = 10', 'H = 50', 'H = 200'], series: [{ name: 'searching', values: [0.67, 0.29, 0.09] }, { name: 'handling', values: [0.33, 0.71, 0.91] }] },
    misconception: 'Ha = aHT is the whole story. That ignores the time lost to handling; it only holds while prey are scarce.', misconceptionFigure: contrast('Do not forget handling.', 'Ha = aHT for all H.', 'Ha = aHT / (1 + aHTh): handling bends the line.'),
    check: { q: 'What does Ha approach as H grows very large?', a: 'aHT / (aHTh) = T / Th: the plateau.', figure: { kind: 'plot', caption: 'Ha → T ÷ Th.', x: [0, 400], y: [0, 12], curves: [{ expr: '0.5*x/(1+0.05*x)' }], hlines: [{ y: 10, label: 'T ÷ Th' }] } }, opens: 'How do you estimate a and Th from data?' },
  { section: 'p7-5', kind: 'derivation', title: 'Fit it with a straight line', ref: 'Fit it with a straight line, p. 7', pages: [7], statement: 'Taking 1 ÷ both sides turns Type II into a straight line: 1/Ha = (1/a)·1/(HT) + Th/T, so lm(I(1/Ha) ~ I(1/(H * T))) gives slope 1/a and intercept Th/T.',
    math: '\\frac{1}{H_a}=\\frac{1}{a}\\cdot\\frac{1}{HT}+\\frac{T_h}{T}',
    explain: [{ text: 'Plot y = 1/Ha against x = 1/(H T): the points fall on a line with slope 1/a and intercept Th/T. With the sheet\'s values the points computed from the model lie exactly on y = 2x + 0.1, so a = 1/2 = 0.5 and Th = 0.1 × T = 0.1, the values the fit recovers.', figure: { kind: 'scatter', caption: 'Five densities (H = 10, 20, 50, 100, 200; T = 1) computed from a = 0.5, Th = 0.1: they lie on y = 2x + 0.1.', points: [[0.1, 0.3], [0.05, 0.2], [0.02, 0.14], [0.01, 0.12], [0.005, 0.11]], fit: 'ols', xlabel: '1 / (H × T)', ylabel: '1 / Ha', animate: true } }],
    code: code([['fit <- lm(I(1/Ha) ~ I(1/(H * T)))', 'regress 1/Ha on 1/(H T); I() makes R do the arithmetic inside the formula'], ['a  <- 1 / coef(fit)[2]   # slope = 1/a', 'the slope is 1/a, so a is its reciprocal'], ['Th <- coef(fit)[1] * T   # Th/T × T', 'the intercept is Th/T, so multiply by T']], ['a = 0.5, Th = 0.1'], 'The linear fit recovers the attack rate and handling time used to make the curves.'),
    terms: [{ term: 'I()', meaning: 'inside a formula: compute this expression literally (not as formula syntax)' }, { term: 'coef(fit)', meaning: 'the fitted intercept and slope' }],
    intuition: 'Turning the curve inside out (1 ÷ both sides) straightens it.', intuitionFigure: flow('Linearise, fit, convert back.', ['1/Ha vs 1/(HT)', 'lm()', 'a = 1/slope', 'Th = intercept × T'], 'LR'),
    misconception: 'In a formula, 1/Ha means "1 divided by Ha" without I(). Formula operators have special meanings; I() is needed.', misconceptionFigure: contrast('I() in formulas.', 'lm(1/Ha ~ 1/(H*T))', 'lm(I(1/Ha) ~ I(1/(H*T)))'),
    check: { q: 'A fit gives slope 4 and intercept 0.2 with T = 2. What are a and Th?', a: 'a = 1/4 = 0.25; Th = 0.2 × 2 = 0.4.', figure: flow('Convert back.', ['slope 4 → a = 0.25', 'intercept 0.2 × T = 2 → Th = 0.4'], 'TB') }, opens: 'How would you fit a Type III response, and which type fits your predator?' }]);
c07.dioramaPlan = [{ subsection: '7.0', count: 0, why: 'the animated plot shows the three shapes' }, { subsection: 'p7-1', count: 0, why: 'a straight line' }, { subsection: 'p7-2', count: 1, why: 'searching and handling: a predator\'s time budget in motion' }, { subsection: 'p7-3', count: 0, why: 'a curve shape' }, { subsection: 'p7-4', count: 0, why: 'algebra on the same time budget (diorama of p7-2)' }, { subsection: 'p7-5', count: 0, why: 'a fitting procedure: figure' }];
out('chain-07.json', c07);

// ============================================================ authored dioramas (the authoring call's answers)
out('scene-holling.json', { type: 'scene', title: 'A predator\'s time budget', technique: 'topdown', environment: { preset: 'landscape', time: 15 }, scale: { m: 1 },
  params: [{ key: 'H', label: 'prey density (prey on the field)', min: 4, max: 60, value: 12, unit: 'prey', rebuild: true }, { key: 'Th', label: 'handling time per prey', min: 0.2, max: 3, value: 1, unit: 's' }, { key: 'a', label: 'search speed', min: 0.5, max: 3, value: 1.5, unit: 'm/s' }],
  bodies: [{ id: 'field', name: 'Field', role: 'decor', shape: { kind: 'disc', r: 6.4 }, material: { preset: 'grass' }, position: [0, 0.01, 0] },
    { id: 'predator', name: 'predator', label: 'Predator', role: 'actor', describe: 'Searches the field, then handles each catch for Th seconds.', shape: { kind: 'cone', r: 0.35, h: 0.8 }, material: { preset: 'leather', color: '#8a4a2a' }, position: [0, 0.4, 0], rotation: [90, 0, 0] },
    { id: 'den', name: 'Den', role: 'decor', shape: { kind: 'rock', r: 0.8, h: 0.6 }, material: { preset: 'stone' }, position: [-5, 0.3, -3] }],
  tour: ['predator'],
  code: "const P = api.body('predator'); const prey = []; const R = 6;\nconst place = o => { const r = R * Math.sqrt(api.rand()), t = 2 * Math.PI * api.rand(); o.position.set(r * Math.cos(t), 0.18, r * Math.sin(t)); };\nfor (let i = 0; i < Math.round(api.param('H')); i++) { const o = api.spawn({ shape: { kind: 'sphere', r: 0.16 }, material: { preset: 'plastic', color: '#f2e2b8' } }); place(o); prey.push(o); }\nlet handling = 0, eaten = 0, tHand = 0, target = null; const dir = api.V3(1, 0, 0);\napi.label('prey', () => prey[0] && prey[0].position, 'One of the prey: eaten prey are replaced, so the density stays H.');\napi.onFrame((dt, t) => {\n  if (handling > 0) { handling -= dt; tHand += dt; if (handling <= 0) api.event('handling done: back to searching', P.position, { id: 'search' }); return; }\n  if (!target || !target.visible) target = prey.reduce((b, o) => !b || o.position.distanceTo(P.position) < b.position.distanceTo(P.position) ? o : b, null);\n  if (!target) return; dir.copy(target.position).sub(P.position); dir.y = 0; const d = dir.length();\n  if (d < 0.3) { eaten++; handling = api.param('Th'); place(target); target = null; api.event('catch: handling for ' + api.fmt(api.param('Th')) + ' s', P.position, { id: 'catch' }); return; }\n  dir.normalize(); P.position.addScaledVector(dir, Math.min(d, api.param('a') * dt)); P.rotation.z = Math.atan2(dir.x, dir.z);\n});\napi.readout('catches per minute', () => api.time() > 1 ? api.fmt(eaten / api.time() * 60) : '—');\napi.readout('share of time handling', () => api.time() > 1 ? api.fmt(tHand / api.time() * 100) + ' %' : '—');\napi.readout('ceiling 60 / Th', () => api.fmt(60 / api.param('Th')) + ' per min');\napi.plot('catches', () => eaten);",
  lessons: [
    { title: 'Scarce prey', question: 'Why does the catch rate level off as prey become common?', text: 'With 6 prey on the field, watch how long the predator walks between catches.', set: { H: 6 }, focus: 'predator', run: 12, explain: 'Most of the time goes into searching: catches rise almost in proportion to prey.', opens: 'What happens when prey are everywhere?' },
    { title: 'Abundant prey', question: 'What happens when prey are everywhere?', text: 'Raise the density to 50 and watch the share of time spent handling.', set: { H: 50 }, focus: 'predator', until: 'event:catch', run: 14, explain: 'Each catch is quickly found but costs Th: handling takes most of the time and the rate nears 60 / Th per minute.', opens: 'What sets the ceiling?' },
    { title: 'Slower handling', question: 'What sets the ceiling?', text: 'Double the handling time and compare the catch rate with the ceiling readout.', set: { H: 50, Th: 2 }, focus: 'predator', run: 14, explain: 'The ceiling is T ÷ Th: doubling Th halves the most a predator can eat, as in Ha = aHT / (1 + aHTh).', opens: 'How would learning or prey switching change the curve?' }],
  sources: [{ title: 'Some characteristics of simple types of predation and parasitism', authors: 'Holling C S', year: 1959, doi: '10.4039/Ent91385-7' }] });
out('scene-function-machine.json', { type: 'scene', title: 'The function machine', technique: 'card', environment: { preset: 'studio' },
  params: [{ key: 'speed', label: 'conveyor speed', min: 0.2, max: 2, value: 0.8, unit: 'm/s' }],
  bodies: [{ id: 'bench', name: 'Workbench', role: 'decor', shape: { kind: 'table', w: 11, d: 3, h: 1 }, material: { preset: 'wood' }, position: [0, 0, 0] },
    { id: 'hopper', name: 'hopper x', label: 'x · the input', role: 'actor', describe: 'Takes in the data you pass to the function.', shape: { kind: 'cone', r: 0.7, h: 1 }, material: { preset: 'brass' }, position: [-4.2, 1.9, 0], rotation: [180, 0, 0] },
    { id: 'sieve', name: 'NA sieve', label: 'x[!is.na(x)]', role: 'actor', describe: 'Drops the missing values.', shape: { kind: 'box', w: 1.4, h: 0.9, d: 1.4, round: 0.05 }, material: { preset: 'steel' }, position: [-1.5, 1.45, 0] },
    { id: 'dial', name: 'sd ÷ √n dial', label: 'sd(x) / sqrt(length(x))', role: 'actor', describe: 'Computes the standard error from what is left.', shape: { kind: 'cylinder', r: 0.7, h: 0.5 }, material: { preset: 'copper' }, position: [1.5, 1.25, 0] },
    { id: 'tray', name: 'output tray', label: 'the output: SE', role: 'actor', describe: 'The last line of the body comes out here.', shape: { kind: 'box', w: 1.4, h: 0.2, d: 1.2 }, material: { preset: 'darkwood' }, position: [4.2, 1.1, 0] },
    { id: 'belt', name: 'Belt', role: 'decor', shape: { kind: 'box', w: 9.5, h: 0.08, d: 0.8 }, material: { preset: 'rubber' }, position: [0, 1.04, 0] }],
  tour: ['hopper', 'sieve', 'dial', 'tray'],
  code: "const tokens = []; let n = 0, dropped = 0;\nfor (let i = 0; i < 12; i++) { const na = i % 4 === 3; const o = api.spawn({ shape: { kind: 'sphere', r: 0.16 }, material: { preset: na ? 'emissive' : 'plastic', color: na ? '#c0392b' : '#2d5b8e' } }); o.position.set(-4.2 - i * 0.6, 1.25, 0); o.userData.na = na; tokens.push(o); }\napi.onFrame(dt => { tokens.forEach(o => { if (!o.visible) return; o.position.x += api.param('speed') * dt; if (o.userData.na && o.position.x > -1.5) { o.visible = false; dropped++; api.event('NA dropped by the sieve', o.position, { id: 'drop' }); } if (o.position.x > 1.5 && !o.userData.counted) { o.userData.counted = true; n++; } if (o.position.x > 4.2) { o.position.x = -4.2 - 6; o.visible = true; o.userData.counted = false; } }); });\napi.readout('n (values kept)', () => n);\napi.readout('NAs dropped', () => dropped);",
  lessons: [
    { title: 'Feed the input', question: 'How does a function turn an input into an output, step by step?', text: 'Watch the value tokens enter the hopper x.', focus: 'hopper x', run: 4, explain: 'x stands in for whatever data the call passes.', opens: 'What happens to the missing values?' },
    { title: 'The sieve', question: 'What happens to the missing values?', text: 'Watch the red NA tokens at the sieve.', focus: 'NA sieve', until: 'event:NA dropped', run: 8, explain: 'x[!is.na(x)] keeps only the present values, so n counts 58 of 62 for the sleep data.', opens: 'What does the dial compute?' },
    { title: 'The output', question: 'What does the dial compute?', text: 'Follow the tokens through the dial to the tray.', focus: 'sd ÷ √n dial', run: 6, explain: 'sd(x) / sqrt(length(x)) is the last line of the body, so it is the output: 0.605 for the sleep data.', opens: 'Which functions will you need in a whole analysis, and in what order?' }] });

