out('gaps-04.json', { steps: [G({ id: 'G1', section: 'p4-3', kind: 'example', title: 'Reading the danger boxplot', ref: 'Boxplot panel, p. 4', pages: [4], answers: 'What do the five boxes show about danger and sleep?', opens: 'What is wrong with a bar of means, and how do you fix it?',
  statement: 'Across danger levels 1 to 5 the boxes sit lower: mammals at high risk of predation sleep less, and the spread inside each level is wide.',
  explain: [{ text: 'Compare the thick median lines from left to right: they fall as danger rises. Compare the boxes too: they overlap, so danger is not the whole story; body size (sheet 04, scatterplot) and diet also matter. A boxplot suggests the pattern; the test of sheet 06 (several groups, so ANOVA or a rank test) says whether it is larger than chance.' }],
  terms: [{ term: 'Danger', meaning: 'danger of predation, an index from 1 (low) to 5 (high)' }],
  intuition: 'An animal that might be eaten cannot afford long, deep sleep.', intuitionFigure: flow('From danger to sleep.', ['high predation risk', 'stay alert', 'less sleep'], 'LR'),
  misconception: 'Falling medians prove that danger reduces sleep.', misconceptionFigure: contrast('A pattern, not yet a cause.', 'Medians fall → danger causes short sleep.', 'Medians fall → test it, and think of body size.'),
  check: { q: 'Which test from sheet 06 compares sleep across the five danger levels?', a: 'ANOVA, summary(aov(TotalSleep ~ factor(Danger))), or a rank test if the boxes are skewed.', figure: flow('Five groups.', ['3+ samples', 'aov() or rank test'], 'LR') } })], coverage: [{ subsection: 'p4-3', steps: ['G1'] }] });
out('gaps-06.json', { steps: [G({ id: 'G1', section: 'p6-1', kind: 'remark', title: 'Check normality first', ref: 'Measured data, p. 6', pages: [6], answers: 'How do you check that data are normal enough for a t test?', opens: 'What if the data are ranks or not normal?',
  statement: 'Before a Z or t test, look at hist() and run shapiro.test(): p > 0.05 means normal enough; a small p means use the rank tests instead.',
  explain: [{ text: 'shapiro.test() asks whether the data could come from a normal distribution. Its p-value works the other way round from most tests: a small p (≤ 0.05) is evidence against normality. The histogram shows why: skew, two peaks or outliers. With large samples tiny departures become significant, so the picture matters as much as the p.', figure: { kind: 'distribution', dist: 'normal', params: { mean: 0, sd: 1 }, caption: 'The shape a t test assumes: one symmetric peak.', xlabel: 'value' } }],
  code: code([['hist(x)', 'look at the shape first'], ['shapiro.test(x)', 'H₀: the data are normal; p > 0.05 → normal enough']], [], 'If Shapiro rejects normality, go to the weakly measured branch (wilcox.test).'),
  terms: [{ term: 'shapiro.test()', meaning: 'Shapiro–Wilk test of normality' }],
  intuition: 'Check that the key fits the lock before you turn it.', intuitionFigure: flow('Check, then choose.', ['hist()', 'shapiro.test()', 'p > 0.05: t test', 'p ≤ 0.05: rank test'], 'LR'),
  misconception: 'A significant Shapiro test is a good result.', misconceptionFigure: contrast('Read it the other way round.', 'p < 0.05 → normal, go ahead.', 'p < 0.05 → not normal: use wilcox.test.'),
  check: { q: 'shapiro.test() gives p = 0.002. Which test do you use for two independent groups?', a: 'Mann–Whitney U, wilcox.test(y ~ group): the data are not normal.', figure: flow('Not normal.', ['p = 0.002', 'rank test'], 'LR') } })], coverage: [{ subsection: 'p6-1', steps: ['G1'] }] });
out('gaps-07.json', { steps: [
  G({ id: 'G1', section: 'p7-4', kind: 'result', title: 'The two limits of the disc equation', ref: 'p. 7', pages: [7], answers: 'What does the disc equation predict at very low and very high prey density?', opens: 'How do you estimate a and Th from data?',
    statement: 'When prey are scarce Ha ≈ aHT (the straight start, slope a × T = 0.5); when prey are abundant Ha → T ÷ Th = 10 (the plateau).',
    math: 'H_a \\approx aHT\\ (aHT_h \\ll 1),\\qquad H_a \\to \\frac{T}{T_h}\\ (aHT_h \\gg 1)',
    explain: [{ text: 'The denominator 1 + aHTh compares the two uses of time. If aHTh is much smaller than 1, handling is negligible and the predator eats in proportion to prey. If it is much larger than 1, handling fills the day and the prey density no longer matters. With a = 0.5 and Th = 0.1 the switch happens around aHTh = 1, at H = 20.', figure: { kind: 'plot', caption: 'The disc equation (a = 0.5, Th = 0.1, T = 1) between its two limits.', x: [0, 200], y: [0, 12], curves: [{ expr: '0.5*x/(1+0.05*x)', label: 'disc equation' }, { expr: '0.5*x', label: 'low-density limit aHT', dash: true }], hlines: [{ y: 10, label: 'high-density limit T ÷ Th' }], vlines: [{ x: 20, label: 'aHTh = 1' }] } }],
    intuition: 'At first the fox is limited by finding rabbits, later by eating them.', intuitionFigure: contrast('Two bottlenecks.', 'One limit for all densities.', 'Scarce prey: search limits; abundant prey: handling limits.'),
    misconception: 'The plateau depends on prey density.', misconceptionFigure: contrast('The ceiling.', 'More prey raises the ceiling.', 'The ceiling is T ÷ Th whatever H is.'),
    check: { q: 'At what H does aHTh = 1 for a = 0.5, Th = 0.1?', a: 'H = 1 / (0.5 × 0.1) = 20.', figure: { kind: 'numberline', caption: 'The switch point.', min: 0, max: 60, step: 10, points: [{ x: 20, label: 'H = 20' }] } } }),
  G({ id: 'G2', section: 'p7-5', kind: 'remark', title: 'Why the straight-line fit is only a start', answers: 'How exact is the straight-line fit with real, noisy data?', opens: 'How would you fit a Type III response, and which type fits your predator?',
    statement: 'Taking 1/Ha magnifies the noise of small catches, so the line is best used for starting values; a nonlinear fit of the curve itself, nls(), is the usual final step.',
    explain: [{ text: 'With real counts, a predator that ate 1 or 2 prey gives 1/Ha = 1 or 0.5, and a single prey more or less changes 1/Ha a lot, while large catches barely move it. Least squares on the transformed scale therefore listens most to the noisiest points. Fitting Ha = aHT/(1 + aHTh) directly by nonlinear least squares, with the line\'s a and Th as starting values, avoids that.' }],
    code: code([['fit2 <- nls(Ha ~ a*H*T/(1 + a*H*Th), start = list(a = 0.5, Th = 0.1))', 'fit the disc equation itself, starting from the straight-line estimates'], ['coef(fit2)', 'the fitted a and Th']], [], 'With the sheet\'s exact values both fits agree: a = 0.5, Th = 0.1.'),
    examples: [{ title: 'Nonlinear fitting of functional responses (added)', origin: 'added', problem: 'Why do ecologists prefer nonlinear fits for functional responses?', solution: [{ text: 'Linearisations distort the error structure; nonlinear least squares (or maximum likelihood) fit the curve on the original scale.' }], answer: 'Use the line for starting values, then nls() or a likelihood fit.', source: { title: 'Nonlinear curve fitting: predation and functional response curves', authors: 'Juliano S A', year: 2001, doi: '', note: 'chapter in Design and Analysis of Ecological Experiments, Oxford University Press' } }],
    terms: [{ term: 'nls()', meaning: 'nonlinear least squares: fits a curve with parameters directly' }],
    intuition: 'Turning numbers upside down also turns their errors upside down.', intuitionFigure: contrast('Noise after 1/x.', 'Every point counts equally after 1/Ha.', 'Small catches become the loudest points after 1/Ha.'),
    misconception: 'If the line fits, the transformation is harmless.', misconceptionFigure: contrast('Fit on the right scale.', 'A straight line on 1/Ha is the best estimate.', 'Use it to start; finish with nls().'),
    check: { q: 'Which points dominate a least-squares fit of 1/Ha?', a: 'Those with small Ha: their 1/Ha values are large and vary most.', figure: flow('Why.', ['small Ha', 'large 1/Ha', 'large residuals', 'dominate the fit'], 'LR') } })],
  coverage: [{ subsection: 'p7-4', steps: ['G1'] }, { subsection: 'p7-5', steps: ['G2'] }] });
